using System.Text;

namespace TKCode.Arc.Foundation.Generators
{
    /// <summary>Writes the code generated for one token class.</summary>
    internal static class TokenEmitter
    {
        private const string Foundation = "global::TKCode.Arc.";
        private const string Parser = "global::TKCode.Arc.ArcTokenValueParser.";

        public static string Emit(TokenModel model)
        {
            var id = model.Stem;
            var kind = id + "TokenKind";
            var tokens = id + "Tokens";
            var descriptor = id + "TokenDescriptor";
            var sb = new StringBuilder();
            sb.AppendLine("// <auto-generated by TKCode.Arc.Foundation.Generators />");
            sb.AppendLine("#nullable enable");
            sb.AppendLine();
            sb.Append("namespace ").AppendLine(model.TokensNamespace);
            sb.AppendLine("{");

            // Kind enum.
            sb.Append("    /// <summary>Token names of the <c>").Append(id).AppendLine("</c> identity. A boxed value is the token's resource key.</summary>");
            sb.Append("    public enum ").AppendLine(kind);
            sb.AppendLine("    {");
            for (var i = 0; i < model.Properties.Count; i++)
            {
                var property = model.Properties[i];
                sb.Append("        /// <summary>Token <c>").Append(property.Name).Append("</c> (").Append(Escape(property.DisplayType)).AppendLine(").</summary>");
                sb.Append("        ").Append(property.Name).Append(" = ").Append(i).AppendLine(",");
            }
            sb.AppendLine("    }");
            sb.AppendLine();

            // Keys and identity.
            sb.Append("    /// <summary>Identity and resource keys of the <c>").Append(id).AppendLine("</c> tokens.</summary>");
            sb.Append("    public static class ").AppendLine(tokens);
            sb.AppendLine("    {");
            sb.AppendLine("        /// <summary>The identity name, used by token overrides.</summary>");
            sb.Append("        public const string Identity = \"").Append(model.Identity).AppendLine("\";");
            sb.AppendLine();
            sb.Append("        internal static readonly object[] KeyTable = new object[] { ");
            for (var i = 0; i < model.Properties.Count; i++)
            {
                if (i > 0)
                {
                    sb.Append(", ");
                }
                sb.Append(kind).Append('.').Append(model.Properties[i].Name);
            }
            sb.AppendLine(" };");
            sb.AppendLine();
            sb.AppendLine("        /// <summary>The resource key of <paramref name=\"kind\"/>: the boxed kind (equal to any other boxing of it), cached.</summary>");
            sb.Append("        public static object Key(").Append(kind).AppendLine(" kind) => KeyTable[(int)kind];");
            sb.AppendLine();
            sb.AppendLine("        /// <summary>The generated descriptor (writer and override parser).</summary>");
            sb.Append("        public static ").Append(Foundation).Append("ArcTokenDescriptor Descriptor => ").Append(descriptor).AppendLine(".Instance;");
            sb.AppendLine("    }");
            sb.AppendLine();

            // Markup extension.
            sb.Append("    /// <summary>Dynamic resource reference to a <c>").Append(id).Append("</c> token, written <c>{arc:").Append(id).AppendLine("TokenResource Name}</c>.</summary>");
            sb.Append("    public sealed class ").Append(id).AppendLine("TokenResourceExtension");
            sb.AppendLine("    {");
            sb.AppendLine("        /// <summary>Creates the extension; set <see cref=\"Kind\"/>.</summary>");
            sb.Append("        public ").Append(id).AppendLine("TokenResourceExtension()");
            sb.AppendLine("        {");
            sb.AppendLine("        }");
            sb.AppendLine();
            sb.AppendLine("        /// <summary>Creates the extension for <paramref name=\"kind\"/>.</summary>");
            sb.Append("        public ").Append(id).Append("TokenResourceExtension(").Append(kind).AppendLine(" kind)");
            sb.AppendLine("        {");
            sb.AppendLine("            Kind = kind;");
            sb.AppendLine("        }");
            sb.AppendLine();
            sb.AppendLine("        /// <summary>The token.</summary>");
            sb.Append("        public ").Append(kind).AppendLine(" Kind { get; set; }");
            sb.AppendLine();
            sb.AppendLine("        /// <summary>Returns a dynamic resource binding to the token's key (local priority, see <c>ArcResourceReference</c>).</summary>");
            sb.AppendLine("        public global::Avalonia.Data.BindingBase ProvideValue(global::System.IServiceProvider serviceProvider)");
            sb.Append("            => global::TKCode.Arc.ArcResourceReference.Create(").Append(tokens).AppendLine(".Key(Kind), serviceProvider);");
            sb.AppendLine("    }");
            sb.AppendLine();

            // Descriptor.
            sb.Append("    internal sealed class ").Append(descriptor).Append(" : ").Append(Foundation).AppendLine("ArcTokenDescriptor");
            sb.AppendLine("    {");
            sb.Append("        public static readonly ").Append(descriptor).Append(" Instance = new ").Append(descriptor).AppendLine("();");
            sb.AppendLine();
            sb.Append("        private ").Append(descriptor).AppendLine("()");
            sb.Append("            : base(").Append(tokens).Append(".Identity, ").Append(model.IsGlobal ? "true" : "false").Append(", new string[] { ");
            for (var i = 0; i < model.Properties.Count; i++)
            {
                if (i > 0)
                {
                    sb.Append(", ");
                }
                sb.Append('"').Append(model.Properties[i].Name).Append('"');
            }
            sb.Append(" }, ").Append(tokens).AppendLine(".KeyTable)");
            sb.AppendLine("        {");
            sb.AppendLine("        }");
            sb.AppendLine();
            sb.Append("        public override ").Append(Foundation).Append("AbstractControlDesignToken CreateToken() => new ").Append(model.FullClassName).AppendLine("();");
            sb.AppendLine();
            sb.Append("        public override void Write(").Append(Foundation).AppendLine("AbstractControlDesignToken token, object?[] values)");
            sb.AppendLine("        {");
            if (model.Properties.Count > 0)
            {
                sb.Append("            var t = (").Append(model.FullClassName).AppendLine(")token;");
            }
            for (var i = 0; i < model.Properties.Count; i++)
            {
                var property = model.Properties[i];
                sb.Append("            values[").Append(i).Append("] = ");
                if (property.Kind == TokenValueKind.Color)
                {
                    sb.Append(Parser).Append("Brush(t.").Append(property.Name).AppendLine(");");
                }
                else
                {
                    sb.Append("t.").Append(property.Name).AppendLine(";");
                }
            }
            sb.AppendLine("        }");
            sb.AppendLine();
            sb.Append("        public override bool TrySetToken(").Append(Foundation).AppendLine("AbstractControlDesignToken token, string name, string value, out string? error)");
            sb.AppendLine("        {");
            if (model.Properties.Count > 0)
            {
                sb.Append("            var t = (").Append(model.FullClassName).AppendLine(")token;");
                sb.AppendLine("            switch (name)");
                sb.AppendLine("            {");
                foreach (var property in model.Properties)
                {
                    sb.Append("                case \"").Append(property.Name).AppendLine("\":");
                    sb.AppendLine("                {");
                    if (property.Kind == TokenValueKind.String)
                    {
                        sb.Append("                    t.").Append(property.Name).AppendLine(" = value;");
                        sb.AppendLine("                    error = null;");
                        sb.AppendLine("                    return true;");
                    }
                    else
                    {
                        sb.Append("                    if (").Append(ParseCall(property)).Append("(value, out ").Append(property.TypeName).AppendLine(" parsed))");
                        sb.AppendLine("                    {");
                        sb.Append("                        t.").Append(property.Name).AppendLine(" = parsed;");
                        sb.AppendLine("                        error = null;");
                        sb.AppendLine("                        return true;");
                        sb.AppendLine("                    }");
                        sb.Append("                    error = InvalidValue(name, \"").Append(Escape(TypeDescription(property))).AppendLine("\", value);");
                        sb.AppendLine("                    return false;");
                    }
                    sb.AppendLine("                }");
                }
                sb.AppendLine("            }");
            }
            sb.AppendLine("            error = UnknownToken(name);");
            sb.AppendLine("            return false;");
            sb.AppendLine("        }");

            // Enum parsers: generated switches, no Enum.Parse.
            var emitted = new System.Collections.Generic.HashSet<string>();
            foreach (var property in model.Properties)
            {
                if (property.Kind != TokenValueKind.Enum || !emitted.Add(property.TypeName))
                {
                    continue;
                }
                sb.AppendLine();
                sb.Append("        private static bool ").Append(EnumParserName(property)).Append("(string text, out ").Append(property.TypeName).AppendLine(" value)");
                sb.AppendLine("        {");
                sb.AppendLine("            switch (text.Trim().ToUpperInvariant())");
                sb.AppendLine("            {");
                foreach (var member in property.EnumMembers)
                {
                    sb.Append("                case \"").Append(member.ToUpperInvariant()).AppendLine("\":");
                    sb.Append("                    value = ").Append(property.TypeName).Append('.').Append(member).AppendLine(";");
                    sb.AppendLine("                    return true;");
                }
                sb.AppendLine("            }");
                sb.AppendLine("            value = default;");
                sb.AppendLine("            return false;");
                sb.AppendLine("        }");
            }

            sb.AppendLine("    }");
            sb.AppendLine("}");
            return sb.ToString();
        }

        private static string ParseCall(TokenProperty property) => property.Kind switch
        {
            TokenValueKind.Color => Parser + "TryParseColor",
            TokenValueKind.Double => Parser + "TryParseDouble",
            TokenValueKind.Int32 => Parser + "TryParseInt32",
            TokenValueKind.Boolean => Parser + "TryParseBoolean",
            TokenValueKind.Thickness => Parser + "TryParseThickness",
            TokenValueKind.CornerRadius => Parser + "TryParseCornerRadius",
            TokenValueKind.BoxShadows => Parser + "TryParseBoxShadows",
            TokenValueKind.FontFamily => Parser + "TryParseFontFamily",
            TokenValueKind.TimeSpan => Parser + "TryParseTimeSpan",
            TokenValueKind.Easing => Parser + "TryParseEasing",
            _ => EnumParserName(property)
        };

        private static string TypeDescription(TokenProperty property) => property.Kind switch
        {
            TokenValueKind.Color => "color (#RRGGBB, #AARRGGBB or a name)",
            TokenValueKind.Double => "number",
            TokenValueKind.Int32 => "integer",
            TokenValueKind.Boolean => "boolean (true or false)",
            TokenValueKind.Thickness => "thickness (1, 2 or 4 numbers)",
            TokenValueKind.CornerRadius => "corner radius (1 or 4 numbers)",
            TokenValueKind.BoxShadows => "box shadow list",
            TokenValueKind.FontFamily => "font family",
            TokenValueKind.TimeSpan => "duration (120ms, 0.2s or 00:00:00.120)",
            TokenValueKind.Easing => "easing (x1,y1,x2,y2 or an easing name)",
            _ => property.DisplayType + " (" + string.Join(", ", property.EnumMembers) + ")"
        };

        private static string EnumParserName(TokenProperty property)
            => "TryParse" + property.TypeName.Replace("global::", string.Empty).Replace(".", "_");

        private static string Escape(string text) => text.Replace("\\", "\\\\").Replace("\"", "\\\"").Replace("<", "&lt;").Replace(">", "&gt;");
    }
}
